// waveformFlags reads out the three nested switches. Showing only the master
// switch would leave "on but not walking history" looking identical to "on and
// working", which is the state operators actually get stuck on.
func waveformFlags(w *storagev1.WaveformStatus) string {
	if !w.Enabled {
		return "disabled"
	}
	mode := "live uploads only"
	if w.BackfillEnabled {
		mode = "live + backfill"
		if w.ArchiveEnabled {
			mode = "live + backfill + archive tier"
		}
	}
	return mode
}

// waveformParams keeps the version fingerprint readable. On its own it is an
// opaque number, so it never appears without the inputs that produced it.
func waveformParams(w *storagev1.WaveformStatus) string {
	return fmt.Sprintf("v%d · alg %d · %d buckets · %d Hz",
		w.Version, w.AlgorithmVersion, w.Buckets, w.SampleRate)
}

func waveformStatusCount(w *storagev1.WaveformStatus, key string) int64 {
	if w.ByStatus == nil {
		return 0
	}
	return w.ByStatus[key]
}

func waveformRunLabel(r *storagev1.WaveformRun) string {
	if r == nil {
		return "not started"
	}
	if r.Exhausted {
		return "caught up"
	}
	return "walking history"
}

func waveformPercent(f float64) string {
	return fmt.Sprintf("%.1f%%", f*100)
}

